  const st={tab:'exam',bankPreview:null,banks:[{name:'离散数学基础题库',count:128,source:'教材解析 · v3',updated:'今天 10:24'},{name:'历年期中试题库',count:86,source:'历史试卷导入',updated:'昨天 16:10'}],exams:[{name:'2026 秋季期中试卷',meta:'12 题 · 100 分',updated:'今天 10:08'},{name:'第 2 次单元测验',meta:'8 题 · 50 分 · v3',updated:'昨天 15:20'}],questions:[{bank:'离散数学基础题库',type:'单选',level:'中等',title:'下列哪项最能体现集合运算的交换律？',options:'A. A∪B=B∪A　B. A∩B=A−B　C. A⊂B　D. A=B',answer:'A',explain:'并集运算满足交换律。',knowledge:'集合与关系 · 集合运算律',source:'离散数学教材第1-3章.pdf',citation:'第 1 章第 12 页：集合的并、交运算'},{bank:'历年期中试题库',type:'简答题',level:'提高',title:'简述欧拉图与哈密顿图的定义及区别。',options:'',answer:'见评分标准',explain:'分别从边遍历和顶点遍历角度说明。',knowledge:'图的连通性 · 欧拉图与哈密顿图',source:'历年期中试卷.docx',citation:'第 3 题：图的遍历'}],materialFlow:{step:1,files:[],questions:[]},ai:{step:0,materials:[{name:'离散数学教材第1-3章.pdf',size:'2.4 MB',status:'已解析'}],points:['集合与关系','图的连通性','欧拉图与哈密顿图','最短路径算法'],search:'',rules:{},questions:[]}};
