  function aiSteps(labels,step){const nums=[1,3,4,5,6];return '<div class="ai-steps">'+labels.map((x,i)=>'<div class="ai-step '+(nums[i]===step?'active ':'')+(nums[i]<step?'done':'')+'"><span>'+((nums[i]<step)?'✓':String(nums[i]).padStart(2,'0'))+'</span><small>'+x+'</small></div>').join('')+'</div>'}
  function aiRulesPage(){const a=st.ai,types=['单选','多选','不定项','填空题','判断题','简答题','论述题','案例分析题'],levels=['基础','中等','提高'];return '<div class="ai-flow"><div class="ai-flow-head"><button class="btn secondary" onclick="examAiBack()">← 上一步</button><div><span class="ai-eyebrow">AI WORKBENCH · 03</span><h2>设置出题规则</h2><p>选择题目类型、难度和对应数量</p></div></div>'+aiSteps(['上传材料并解析知识点','设置出题规则','出题进度','题目预览','入库'],3)+'<section class="exam-card"><div class="exam-card-head"><div><h3>题型与难度配置</h3><p class="exam-import-note">在中间填写每种题型、难度的数量，0 表示不生成。</p></div><span class="exam-badge">共 '+a.points.length+' 个知识点</span></div><div class="exam-type-matrix ai-rule-matrix"><span>题目类型</span>'+levels.map(l=>'<span>'+l+'</span>').join('')+types.map((t,i)=>'<span class="matrix-label">'+t+'</span>'+levels.map((l,j)=>'<input type="number" min="0" value="'+(a.rules[i+'-'+j]||0)+'" onchange="examAiRule(\''+i+'-'+j+'\',this.value)" aria-label="'+t+' '+l+'数量">').join('')).join('')+'</div><div class="ai-rule-summary"><b>'+Object.values(a.rules).reduce((n,v)=>n+(Number(v)||0),0)+' 题</b><span>预计生成数量 · 确认规则后开始 AI 出题</span></div></section><div class="ai-flow-actions"><button class="btn primary" onclick="examAiStart()">开始 AI 出题</button></div></div>'}
  function aiPreviewPage(){const a=st.ai;return '<div class="ai-flow"><div class="ai-flow-head"><button class="btn secondary" onclick="examAiBack()">← 返回进度</button><div><span class="ai-eyebrow">AI WORKBENCH · 05</span><h2>题目预览</h2><p>预览并编辑 AI 生成的完整题目内容</p></div><span class="exam-badge">已生成 '+a.questions.length+' 题</span></div>'+aiSteps(['上传材料并解析知识点','设置出题规则','出题进度','题目预览','入库'],5)+'<div class="ai-preview-list">'+a.questions.map((q,i)=>'<article class="exam-card ai-question"><div class="ai-question-head"><span class="exam-badge">'+q.type+'</span><span>'+q.level+'</span><button class="btn secondary" onclick="examAiEdit('+i+')">编辑</button><button class="btn secondary" onclick="examAiDelete('+i+')">删除</button></div><h3>'+esc(q.title)+'</h3><p>'+esc(q.options||'')+'</p><div class="ai-answer"><b>答案</b> '+esc(q.answer)+'</div><div class="ai-explain"><b>解析</b> '+esc(q.explain)+'</div><div class="ai-source"><div><b>对应知识点</b><span>'+esc(q.knowledge||'未关联知识点')+'</span></div><div><b>教材 / 知识库来源</b><span>'+esc(q.source||'未填写来源')+'</span></div><div><b>引用内容</b><span>'+esc(q.citation||'未填写引用片段')+'</span></div></div></article>').join('')+'</div><div class="ai-flow-actions"><button class="btn secondary" onclick="examAiAddQuestion()">＋ 添加题目</button><button class="btn primary" onclick="examAiNext()">确认题目，选择题库</button></div></div>'}
  function aiImportPage(){const a=st.ai;return '<div class="ai-flow"><div class="ai-flow-head"><button class="btn secondary" onclick="examAiBack()">← 返回预览</button><div><span class="ai-eyebrow">AI WORKBENCH · 06</span><h2>入库</h2><p>选择题目目录，确认后将题目写入题库</p></div></div>'+aiSteps(['上传材料并解析知识点','设置出题规则','出题进度','题目预览','入库'],6)+'<section class="exam-card"><h3>选择目标题库</h3><div class="exam-form"><label>题目目录<select id="aiImportBank">'+st.banks.map(b=>'<option>'+esc(b.name)+'</option>').join('')+'</select></label></div><div class="ai-import-summary"><b>'+a.questions.length+' 道题目</b><span>将导入所选题目目录，后续可继续编辑。</span></div></section><div class="ai-flow-actions"><button class="btn primary" onclick="examAiConfirmImport()">确认并导入题库</button></div></div>'}
  function bankPreviewPage(){const b=st.banks[st.bankPreview],qs=st.questions.filter(q=>q.bank===b.name);return '<div class="ai-flow"><div class="ai-flow-head"><button class="btn secondary" onclick="examBankBack()">← 返回我的题库</button><div><span class="ai-eyebrow">题库详情</span><h2>'+esc(b.name)+'</h2><p>'+b.count+' 道题 · '+esc(b.source)+' · 更新于 '+esc(b.updated)+'</p></div><span class="exam-badge">'+qs.length+' 条已展示</span></div><div class="ai-preview-list">'+(qs.length?qs.map(q=>'<article class="exam-card ai-question"><div class="ai-question-head"><span class="exam-badge">'+esc(q.type||'未分类')+'</span><span>'+esc(q.level||'未设置')+'</span></div><h3>'+esc(q.title||'未填写题干')+'</h3><p>'+esc(q.options||'')+'</p><div class="ai-answer"><b>答案</b> '+esc(q.answer||'未填写')+'<br><b>解析</b> '+esc(q.explain||'未填写')+'</div><div class="ai-source"><div><b>对应知识点</b><span>'+esc(q.knowledge||'未关联知识点')+'</span></div><div><b>教材 / 知识库来源</b><span>'+esc(q.source||'未填写来源')+'</span></div><div><b>引用内容</b><span>'+esc(q.citation||'未填写引用片段')+'</span></div></div></article>').join(''):'<section class="exam-card"><h3>题库暂无可展示题目</h3><p class="exam-import-note">可以通过 AI 生成题目或上传试卷后导入。</p></section>')+'</div></div>'}
  function bankPage(){if(st.bankPreview!==null)return bankPreviewPage();return '<div class="exam-toolbar"><div><h2>题库工作台</h2><p>创建题目目录、导入历史素材，或基于课程资料生成新题目</p></div><div class="exam-actions"><button class="btn secondary" onclick="examNewBank()">＋ 创建题库</button><button class="btn secondary" onclick="examOpen(\'素材上传\')">上传题库素材</button><button class="btn primary" onclick="examAiOpen()">AI 生成题目</button></div></div><div class="exam-stats"><div class="exam-stat"><span>题库数量</span><strong>'+st.banks.length+'</strong><small>当前课程</small></div><div class="exam-stat"><span>题目总数</span><strong>'+st.banks.reduce((n,b)=>n+b.count,0)+'</strong><small>已确认题目</small></div><div class="exam-stat"><span>待确认解析</span><strong>6</strong><small>来自 2 个文件</small></div><div class="exam-stat"><span>知识点覆盖</span><strong>92%</strong><small>v3 课程大纲</small></div></div><div class="exam-grid"><section class="exam-card"><div class="exam-card-head"><h3>我的题库</h3><span class="exam-badge">可维护</span></div><div class="exam-list">'+st.banks.map((b,i)=>'<div class="exam-row"><b>'+esc(b.name)+'</b><small>'+b.count+' 道题 · '+esc(b.source)+' · 更新于 '+b.updated+'</small><div class="exam-row-actions"><button class="btn secondary" onclick="examPreviewBank('+i+')">预览题目</button><button class="btn secondary" onclick="alert(\'题目目录可继续编辑和录入题目\')">编辑</button></div></div>').join('')+'</div></section></div>'}
  function paperPage(){return '<div class="exam-toolbar"><div><h2>试卷工作台</h2><p>管理已有试卷、解析上传试卷，或按规则智能组卷</p></div><div class="exam-actions"><button class="btn secondary" onclick="examOpen(\'上传已有试卷\')">上传已有试卷</button><button class="btn primary" onclick="examOpen(\'AI 智能组卷\')">AI 智能组卷</button></div></div><div class="exam-stats"><div class="exam-stat"><span>试卷总数</span><strong>'+st.exams.length+'</strong><small>当前课程</small></div><div class="exam-stat"><span>最近更新</span><strong>'+((st.exams[0]&&st.exams[0].updated)||'刚刚')+'</strong><small>最近一次变更</small></div><div class="exam-stat"><span>题目总数</span><strong>'+st.exams.reduce((n,e)=>n+(parseInt(e.meta,10)||0),0)+'</strong><small>已配置题目</small></div><div class="exam-stat"><span>可导出</span><strong>'+st.exams.length+'</strong><small>支持 PDF / Word</small></div></div><section class="exam-card"><div class="exam-card-head"><h3>已有试卷</h3><span class="exam-badge">共 '+st.exams.length+' 份</span></div><div class="exam-list">'+st.exams.map((e,i)=>'<div class="exam-row"><b>'+esc(e.name)+'</b><small>'+e.meta+' · 更新于 '+(e.updated||'刚刚')+'</small><div class="exam-row-actions"><button class="btn secondary" onclick="alert(\'试卷预览：题目、分值、答案与评分标准\')">预览</button><button class="btn secondary" onclick="alert(\'已生成 PDF 导出任务\')">下载 PDF</button><button class="btn secondary" onclick="alert(\'已生成 Word 导出任务\')">Word</button></div></div>').join('')+'</div></section>'}
  window.examAiOpen=()=>{st.tab='bank';st.ai.step=1;render()};window.examAiBack=()=>{const prev={3:1,4:3,5:4,6:5};st.ai.step=prev[st.ai.step]||0;render()};window.examAiUpload=input=>{[...(input.files||[])].forEach(f=>st.ai.materials.push({name:f.name,size:Math.round(f.size/1024)+' KB',status:'待解析'}));render()};window.examAiParse=i=>{st.ai.materials[i].status='已解析';if(!st.ai.points.length)st.ai.points=['核心概念与定义','典型例题与方法'];render()};window.examAiPoint=(i,v)=>{st.ai.points[i]=v};window.examAiSearch=v=>{st.ai.search=v;render()};window.examAiRemovePoint=i=>{st.ai.points.splice(i,1);render()};window.examAiAddPoint=()=>{st.ai.points.push('新知识点');render()};window.examAiNext=()=>{st.ai.step=st.ai.step===5?6:3;render()};window.examAiRule=(k,v)=>{st.ai.rules[k]=Math.max(0,parseInt(v,10)||0)};window.examAiStart=()=>{st.ai.step=4;render();setTimeout(()=>{st.ai.questions=[{type:'单选',level:'中等',score:5,title:'下列哪项最能体现集合运算的交换律？',options:'A. A∪B=B∪A　B. A∩B=A−B　C. A⊂B　D. A=B',answer:'A',explain:'并集运算满足交换律。',knowledge:'集合与关系 · 集合运算律',source:'离散数学教材第1-3章.pdf',citation:'第 1 章第 12 页：集合的并、交运算'},{type:'简答题',level:'提高',score:10,title:'简述欧拉图与哈密顿图的定义及区别。',options:'',answer:'见评分标准',explain:'分别从边遍历和顶点遍历角度说明。',knowledge:'图的连通性 · 欧拉图与哈密顿图',source:'离散数学教材第1-3章.pdf',citation:'第 3 章第 48 页：图的遍历'}];st.ai.step=5;render()},900)};window.examAiPreview=()=>{st.ai.step=5;if(!st.ai.questions.length)st.ai.questions=[{type:'单选',level:'中等',score:5,title:'下列哪项最能体现集合运算的交换律？',options:'A. A∪B=B∪A　B. A∩B=A−B　C. A⊂B　D. A=B',answer:'A',explain:'并集运算满足交换律。',knowledge:'集合与关系 · 集合运算律',source:'离散数学教材第1-3章.pdf',citation:'第 1 章第 12 页：集合的并、交运算'}];render()};
  const choiceTypes=['单选','多选','不定项'];const questionOptions=q=>Array.isArray(q.options)?q.options:(q.options||'').split(/\s*(?=[A-H]\.\s)/).map(x=>x.replace(/^[A-H]\.\s*/,'').trim()).filter(Boolean);window.examAiRenderOptions=()=>{const type=document.getElementById('aiQType')?.value,wrap=document.getElementById('aiQOptionsWrap');if(!wrap)return;if(!choiceTypes.includes(type)){wrap.innerHTML='<label>选项（填空题、简答题可留空）<textarea id="aiQOptions"></textarea></label>';return}const vals=window.__examOptionDraft||['','','',''];wrap.innerHTML='<div class="ai-options-editor"><div class="ai-options-title"><b>选项配置</b><button type="button" class="btn secondary" onclick="examAiOptionAdd()">＋ 添加选项</button></div>'+vals.map((v,i)=>'<div class="ai-option-row"><span>'+String.fromCharCode(65+i)+'</span><input class="ai-option-input" data-index="'+i+'" value="'+esc(v)+'" placeholder="填写选项内容"><button type="button" aria-label="删除选项" onclick="examAiOptionDelete('+i+')">×</button></div>').join('')+'</div>'};window.examAiOptionAdd=()=>{const inputs=[...document.querySelectorAll('.ai-option-input')];window.__examOptionDraft=inputs.map(x=>x.value).concat('');examAiRenderOptions()};window.examAiOptionDelete=i=>{const inputs=[...document.querySelectorAll('.ai-option-input')];window.__examOptionDraft=inputs.map(x=>x.value).filter((_,n)=>n!==i);if(!window.__examOptionDraft.length)window.__examOptionDraft=[''];examAiRenderOptions()};window.examAiQuestionModal=i=>{const q=i<0?{type:'单选',level:'中等',score:5,title:'',options:'',answer:'',explain:'',knowledge:'',source:'',citation:''}:st.ai.questions[i],types=['单选','多选','不定项','填空题','判断题','简答题','论述题','案例分析题'];window.__examOptionDraft=choiceTypes.includes(q.type)?questionOptions(q):[];const field=(id,label,value,area)=>'<label>'+label+(area?'<textarea id="'+id+'">'+esc(value||'')+'</textarea>':'<input id="'+id+'" value="'+esc(value||'')+'">')+'</label>';document.body.insertAdjacentHTML('beforeend','<div class="exam-modal-bg"><div class="exam-modal ai-question-modal"><div class="exam-modal-head"><div><span class="ai-eyebrow">题目编辑器</span><h3>'+(i<0?'添加题目':'编辑题目')+'</h3></div><button class="exam-close" onclick="examClose()">×</button></div><div class="ai-question-form"><div class="ai-question-fields"><label>题目类型<select id="aiQType" onchange="examAiRenderOptions()">'+types.map(t=>'<option '+(t===q.type?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label>难度<select id="aiQLevel"><option '+(q.level==='基础'?'selected':'')+'>基础</option><option '+(q.level==='中等'?'selected':'')+'>中等</option><option '+(q.level==='提高'?'selected':'')+'>提高</option></select></label><label>分值<input id="aiQScore" type="number" min="1" value="'+(q.score||5)+'"></label></div>'+field('aiQTitle','题干',q.title,true)+'<div id="aiQOptionsWrap"></div>'+field('aiQAnswer','答案',q.answer,true)+field('aiQExplain','解析',q.explain,true)+'<div class="ai-source-fields"><h4>知识点与引用依据</h4>'+field('aiQKnowledge','对应知识点',q.knowledge,true)+field('aiQSource','教材 / 知识库来源',q.source,true)+field('aiQCitation','引用内容 / 页码',q.citation,true)+'</div></div><div class="exam-modal-actions"><button class="btn secondary" onclick="examClose()">取消</button><button class="btn primary" onclick="examAiSaveQuestion('+i+')">保存题目</button></div></div></div>');examAiRenderOptions()};window.examAiSaveQuestion=i=>{const type=document.getElementById('aiQType').value,optionInputs=[...document.querySelectorAll('.ai-option-input')],options=choiceTypes.includes(type)?optionInputs.map(x=>x.value.trim()).filter(Boolean).map((x,n)=>String.fromCharCode(65+n)+'. '+x).join('　'):document.getElementById('aiQOptions').value.trim(),q={type,level:document.getElementById('aiQLevel').value,score:Number(document.getElementById('aiQScore').value)||5,title:document.getElementById('aiQTitle').value.trim(),options,answer:document.getElementById('aiQAnswer').value.trim(),explain:document.getElementById('aiQExplain').value.trim(),knowledge:document.getElementById('aiQKnowledge').value.trim(),source:document.getElementById('aiQSource').value.trim(),citation:document.getElementById('aiQCitation').value.trim()};if(!q.title){alert('请填写题干');return}if(choiceTypes.includes(type)&&!options){alert('请至少填写一个选项');return}if(i<0)st.ai.questions.push(q);else st.ai.questions[i]=q;close();render()};window.examAiEdit=i=>window.examAiQuestionModal(i);window.examAiDelete=i=>{st.ai.questions.splice(i,1);render()};window.examAiAddQuestion=()=>window.examAiQuestionModal(-1);window.examAiConfirmImport=()=>{const bank=st.banks.find(b=>b.name===document.getElementById('aiImportBank')?.value)||st.banks[0];st.questions.push(...st.ai.questions.map(q=>({...q,bank:bank.name})));bank.count+=st.ai.questions.length;bank.updated='刚刚';const count=st.ai.questions.length;st.ai.step=0;st.tab='bank';render();alert('已成功导入 '+count+' 道题目到“'+bank.name+'”')};
  function materialRender(){const f=st.materialFlow,step='<div class="exam-stepper"><span class="exam-step '+(f.step>=1?'active':'')+'">1 上传素材</span><span class="exam-step '+(f.step>=2?'active':'')+'">2 AI 解析</span><span class="exam-step '+(f.step>=3?'active':'')+'">3 核对入库</span></div>';let body=f.step===1?'<div class="exam-form"><label>选择题库素材<input type="file" multiple accept=".doc,.docx,.pdf,.txt,.ppt,.pptx,.png,.jpg" onchange="examMaterialFiles(this)"></label><p class="exam-import-note">支持 Word、PDF、TXT、PPT 和图片，可同时上传多个文件。系统会识别题干、题型、选项、答案、解析和知识点。</p><div class="material-file-list">'+(f.files.length?f.files.map((x,i)=>'<div class="material-file"><div><b>'+esc(x.name)+'</b><small>'+x.size+' · '+x.status+'</small></div><button class="btn secondary" onclick="examMaterialParse('+i+')">'+(x.status==='已解析'?'重新解析':'开始解析')+'</button></div>').join(''):'<div class="material-empty">还没有上传素材</div>')+'</div></div>':f.step===2?'<div class="exam-import-summary"><strong>AI 解析完成</strong><span>已从 '+f.files.length+' 个文件中识别 '+f.questions.length+' 道题目。</span><div class="exam-import-meta"><b>题型覆盖</b><span>单选、多选、不定项、填空题、判断题、简答题、论述题、案例分析题</span><b>可入库题目</b><span>'+f.questions.filter(q=>q.on).length+' 道</span></div></div><p class="exam-import-note">下一步将逐题核对解析结果，确认后选择目标题库。</p>':'<p class="exam-import-note">勾选需要入库的题目，可直接修改题干、答案和解析。</p><div class="exam-form"><label>导入到题目目录<select id="materialBank">'+st.banks.map(b=>'<option>'+esc(b.name)+'</option>').join('')+'</select></label>'+f.questions.map((q,i)=>'<div class="material-question"><label><input type="checkbox" '+(q.on?'checked':'')+' onchange="examMaterialToggle('+i+',this.checked)"><span><b>'+esc(q.type)+'</b> · '+esc(q.title)+'</span></label><button class="btn secondary" onclick="examMaterialEdit('+i+')">编辑</button></div>').join('')+'</div>';const m=document.querySelector('.exam-modal');if(!m)return;m.innerHTML='<div class="exam-modal-head"><h3>上传题库素材</h3><button class="exam-close" onclick="examClose()">×</button></div>'+step+body+'<div class="exam-modal-actions"><button class="btn secondary" onclick="examClose()">取消</button><button class="btn primary" onclick="'+(f.step===1?'examMaterialStart()':f.step===2?'examMaterialReview()':'examMaterialConfirm()')+'">'+(f.step===1?'开始解析':f.step===2?'进入题目核对':'确认并入库')+'</button></div>'}
  function materialOpen(){st.materialFlow={step:1,files:[],questions:[]};document.body.insertAdjacentHTML('beforeend','<div class="exam-modal-bg"><div class="exam-modal"></div></div>');materialRender()};window.examMaterialFiles=input=>{[...(input.files||[])].forEach(x=>st.materialFlow.files.push({name:x.name,size:Math.max(1,Math.round(x.size/1024))+' KB',status:'待解析'}));materialRender()};window.examMaterialParse=i=>{st.materialFlow.files[i].status='已解析';if(!st.materialFlow.questions.length)st.materialFlow.questions=importQs.map(q=>({...q,on:true,source:st.materialFlow.files[i].name,knowledge:'待核对知识点',citation:'素材解析结果'}));materialRender()};window.examMaterialStart=()=>{st.materialFlow.files.forEach(x=>x.status='已解析');if(!st.materialFlow.questions.length)st.materialFlow.questions=importQs.map(q=>({...q,on:true,source:st.materialFlow.files[0]?.name||'题库素材',knowledge:'待核对知识点',citation:'素材解析结果'}));st.materialFlow.step=2;materialRender()};window.examMaterialReview=()=>{st.materialFlow.step=3;materialRender()};window.examMaterialToggle=(i,v)=>{st.materialFlow.questions[i].on=v};window.examMaterialEdit=i=>{const q=st.materialFlow.questions[i],title=prompt('修改题干',q.title),answer=title===null?null:prompt('修改答案',q.answer);if(title!==null&&title.trim())q.title=title.trim();if(answer!==null)q.answer=answer.trim();materialRender()};window.examMaterialConfirm=()=>{const bank=st.banks.find(b=>b.name===document.getElementById('materialBank')?.value)||st.banks[0],picked=st.materialFlow.questions.filter(q=>q.on);st.questions.push(...picked.map(q=>{const {score,...clean}=q;return {...clean,bank:bank.name}}));bank.count+=picked.length;bank.updated='刚刚';close();render();alert('素材解析成功，已将 '+picked.length+' 道题目导入“'+bank.name+'”')};
